import { registerSW } from 'virtual:pwa-register';
import { pwaStore } from './pwaStore';

/**
 * Register the Workbox service worker generated by vite-plugin-pwa.
 * It only caches the app's own static files (the "app shell") so the app
 * opens without internet. It never sees or stores transaction data.
 */
export function registerServiceWorker(): void {
  if (!('serviceWorker' in navigator)) return;
  const updateSW = registerSW({
    onOfflineReady() {
      pwaStore.setOfflineReady(true);
    },
    onNeedRefresh() {
      pwaStore.setUpdateAvailable(() => updateSW(true));
    },
    onRegisteredSW(_url, registration) {
      // On later visits the shell is already cached, so the app is ready offline.
      if (registration?.active) pwaStore.setOfflineReady();
    },
    onRegisterError() {
      // Offline access is unavailable, but the app itself keeps working.
    },
  });
}
